function resetGame(seed) {
    Math.random = mulberry32(seed >>> 0);
    score = 0;
    lives = 1;
    gameState = 'PLAYING';

    for (let l of lanes) {
        scene.remove(l.mesh);
        for (let e of l.entities) scene.remove(e.mesh);
    }
    lanes = [];
    prevType = 0;
    typeCount = 0;
    maxZ_reached = 0;

    playerTargetX = 0;
    playerTargetZ = 0;
    playerJumpTimer = 0;
    onLog = null;
    player.position.set(0, 0.8, 0);

    lowestZ_generated = 5;
    while (lowestZ_generated >= -30) {
        generateLane(lowestZ_generated);
        lowestZ_generated--;
    }

    updateCamera(0);
}
